<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { cambiarEstadoPersonaEstudio, descargarSustentoEstudio, guardarPersonaEstudio, listarDepartamentosEstudios, listarDistritosEstudios, listarOpcionesPersonaEstudios, listarPersonaEstudios, listarProvinciasEstudios } from '../services/personaEstudios'
import type { EstudioCatalogo, EstudioPersona, PersonaEstudio, PersonaEstudioPayload } from '../interfaces/personaEstudios.interface'
const rows=ref<PersonaEstudio[]>([]),personas=ref<EstudioPersona[]>([]),grados=ref<EstudioCatalogo[]>([]),centros=ref<EstudioCatalogo[]>([]),paises=ref<EstudioCatalogo[]>([]),departamentos=ref<EstudioCatalogo[]>([]),provincias=ref<EstudioCatalogo[]>([]),distritos=ref<EstudioCatalogo[]>([]),paisId=ref<number|null>(null),departamentoId=ref<number|null>(null),criterio=ref(''),personaFiltro=ref<number|null>(null),page=ref(1),lastPage=ref(1),total=ref(0),maxMb=ref(20),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),editing=ref<number|null>(null);const defaults:PersonaEstudioPayload={persona_id:0,gradoinstruccion_id:0,centroensenanza_id:0,provincia_id:null,distrito_id:null,fechadesde:null,fechahasta:null,califica:null,nota:null,sustento:null};const form=reactive<PersonaEstudioPayload>({...defaults});const message=(v:unknown)=>v instanceof Error?v.message:'No se pudo completar la operación.'
const cat=(x:EstudioCatalogo|null|undefined)=>x?.descripcion??x?.nombre??'—';const grade=(x:PersonaEstudio)=>x.grado_instruccion??x.gradoInstruccion;const center=(x:PersonaEstudio)=>x.centro_ensenanza??x.centroEnsenanza;const date=(v:string|null)=>v?new Date(`${v.slice(0,10)}T00:00:00`).toLocaleDateString('es-PE'):'—';const location=(x:PersonaEstudio)=>[x.pais?.nombre,x.departamento?.nombre,x.provincia?.nombre,x.distrito?.nombre].filter(Boolean).join(' / ')||'—'
async function options(){try{const r=await listarOpcionesPersonaEstudios();personas.value=r.personas;grados.value=r.grados_instruccion;centros.value=r.centros_ensenanza;paises.value=r.paises;maxMb.value=r.maximo_archivo_mb||20}catch(v){error.value=message(v)}}async function load(reset=false){if(reset)page.value=1;loading.value=true;error.value='';try{const r=await listarPersonaEstudios(criterio.value,page.value,personaFiltro.value);rows.value=r.data;total.value=r.total;page.value=r.current_page;lastPage.value=r.last_page}catch(v){error.value=message(v)}finally{loading.value=false}}
async function countryChanged(){departamentoId.value=null;form.provincia_id=null;form.distrito_id=null;provincias.value=[];distritos.value=[];departamentos.value=paisId.value?await listarDepartamentosEstudios(paisId.value):[]}async function departmentChanged(){form.provincia_id=null;form.distrito_id=null;distritos.value=[];provincias.value=departamentoId.value?await listarProvinciasEstudios(departamentoId.value):[]}async function provinceChanged(){form.distrito_id=null;distritos.value=form.provincia_id?await listarDistritosEstudios(form.provincia_id):[]}
function openCreate(){editing.value=null;Object.assign(form,defaults,{persona_id:personaFiltro.value??0});paisId.value=null;departamentoId.value=null;departamentos.value=[];provincias.value=[];distritos.value=[];error.value='';modal.value=true}
async function openEdit(x:PersonaEstudio){editing.value=x.id;Object.assign(form,{persona_id:x.persona_id,gradoinstruccion_id:x.gradoinstruccion_id,centroensenanza_id:x.centroensenanza_id,provincia_id:x.provincia_id,distrito_id:x.distrito_id,fechadesde:x.fechadesde?.slice(0,10)??null,fechahasta:x.fechahasta?.slice(0,10)??null,califica:x.califica,nota:x.nota,sustento:null});paisId.value=x.pais?.id??null;departamentoId.value=x.departamento?.id??null;try{departamentos.value=paisId.value?await listarDepartamentosEstudios(paisId.value):[];provincias.value=departamentoId.value?await listarProvinciasEstudios(departamentoId.value):[];distritos.value=x.provincia_id?await listarDistritosEstudios(x.provincia_id):[]}catch(v){error.value=message(v)}modal.value=true}
function fileSelected(e:Event){form.sustento=(e.target as HTMLInputElement).files?.[0]??null}function validate(){if(!form.persona_id||!form.gradoinstruccion_id||!form.centroensenanza_id)return 'Persona, grado y centro de enseñanza son obligatorios.';if(form.fechadesde&&form.fechahasta&&form.fechahasta<form.fechadesde)return 'La fecha hasta debe ser mayor o igual a la fecha desde.';if((form.califica?.length??0)>100||(form.nota?.length??0)>100)return 'Calificación y nota admiten hasta 100 caracteres.';if(form.sustento&&(form.sustento.type!=='application/pdf'||form.sustento.size>maxMb.value*1024*1024))return `El sustento debe ser PDF y no superar ${maxMb.value} MB.`;return ''}
async function save(){const issue=validate();if(issue)return void(error.value=issue);saving.value=true;error.value='';try{await guardarPersonaEstudio(editing.value,{...form,califica:form.califica?.trim()||null,nota:form.nota?.trim()||null});modal.value=false;success.value=`Estudio ${editing.value?'actualizado':'registrado'} correctamente.`;await load()}catch(v){error.value=message(v)}finally{saving.value=false}}async function toggle(x:PersonaEstudio){const action=x.estado?'desactivar':'activar';if(!confirm(`¿Desea ${action} este estudio?`))return;try{const r=await cambiarEstadoPersonaEstudio(x.id);x.estado=r.estado;success.value=r.message??`Estudio ${r.estado?'activado':'desactivado'} correctamente.`}catch(v){error.value=message(v)}}async function download(x:PersonaEstudio){try{await descargarSustentoEstudio(x.id)}catch(v){error.value=message(v)}}function move(v:number){if(v<1||v>lastPage.value)return;page.value=v;load()}onMounted(()=>Promise.all([options(),load()]))
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Recursos Humanos / Estudios por trabajador</nav><header class="hero"><div class="mark">ET</div><div><small>MIA · RECURSOS HUMANOS · MAESTROS</small><h1>Estudios por trabajador</h1><p>Historial académico, instituciones, periodos, ubicación y documentos de sustento.</p></div><strong>{{total}} estudios</strong></header><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error" class="flash">{{error}}</p><section class="filters"><label>Trabajador<select v-model="personaFiltro" @change="load(true)"><option :value="null">Todos</option><option v-for="x in personas" :key="x.id" :value="x.id">{{x.nombre_completo}} · {{x.dni||'Sin DNI'}}</option></select></label><form @submit.prevent="load(true)"><label>Buscar<input v-model.trim="criterio" placeholder="Grado, centro, calificación o persona"></label><button>Buscar</button></form><button class="new" @click="openCreate">Registrar estudio</button></section><section class="table-card"><header><small>HISTORIAL ACADÉMICO</small><h2>Estudios registrados</h2></header><div v-if="loading" class="empty">Consultando estudios…</div><div v-else-if="!rows.length" class="empty">No se encontraron estudios.</div><div v-else class="scroll"><table><thead><tr><th>Trabajador</th><th>Grado</th><th>Centro</th><th>Ubicación</th><th>Periodo</th><th>Calificación / nota</th><th>Sustento</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="x in rows" :key="x.id"><td><b>{{x.persona?.nombre_completo??`Persona #${x.persona_id}`}}</b><small>DNI: {{x.persona?.dni||'—'}}</small></td><td>{{cat(grade(x))}}</td><td>{{cat(center(x))}}</td><td>{{location(x)}}</td><td>{{date(x.fechadesde)}}<small>al {{date(x.fechahasta)}}</small></td><td>{{x.califica||'—'}}<small>Nota: {{x.nota||'—'}}</small></td><td><button v-if="x.sustento" class="link" @click="download(x)">Descargar PDF</button><span v-else>—</span></td><td><span :class="x.estado?'active':'inactive'">{{x.estado?'Activo':'Inactivo'}}</span></td><td class="actions"><button class="edit" @click="openEdit(x)">Editar</button><button :class="x.estado?'disable':'enable'" @click="toggle(x)">{{x.estado?'Desactivar':'Activar'}}</button></td></tr></tbody></table></div><footer v-if="lastPage>1"><button :disabled="page<=1" @click="move(page-1)">Anterior</button><span>Página {{page}} de {{lastPage}}</span><button :disabled="page>=lastPage" @click="move(page+1)">Siguiente</button></footer></section><div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="dialog" @submit.prevent="save"><header><div class="mark">ET</div><div><small>{{editing?'ACTUALIZAR ESTUDIO':'NUEVO ESTUDIO'}}</small><h2>{{editing?'Editar':'Registrar'}} estudio</h2></div><button type="button" class="close" @click="modal=false">×</button></header><div class="grid"><label class="full">Trabajador *<select v-model="form.persona_id" :disabled="editing!==null"><option :value="0">Seleccione</option><option v-for="x in personas" :key="x.id" :value="x.id">{{x.nombre_completo}} · DNI {{x.dni||'—'}}</option></select></label><label>Grado de instrucción *<select v-model="form.gradoinstruccion_id"><option :value="0">Seleccione</option><option v-for="x in grados" :key="x.id" :value="x.id">{{x.codigo}} · {{cat(x)}}</option></select></label><label>Centro de enseñanza *<select v-model="form.centroensenanza_id"><option :value="0">Seleccione</option><option v-for="x in centros" :key="x.id" :value="x.id">{{x.codigo}} · {{cat(x)}}</option></select></label><label>País<select v-model="paisId" @change="countryChanged"><option :value="null">Sin ubicación</option><option v-for="x in paises" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Departamento<select v-model="departamentoId" :disabled="!paisId" @change="departmentChanged"><option :value="null">Seleccione</option><option v-for="x in departamentos" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Provincia<select v-model="form.provincia_id" :disabled="!departamentoId" @change="provinceChanged"><option :value="null">Seleccione</option><option v-for="x in provincias" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Distrito<select v-model="form.distrito_id" :disabled="!form.provincia_id"><option :value="null">Seleccione</option><option v-for="x in distritos" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Fecha desde<input v-model="form.fechadesde" type="date"></label><label>Fecha hasta<input v-model="form.fechahasta" type="date"></label><label>Calificación<input v-model="form.califica" maxlength="100"></label><label>Nota<input v-model="form.nota" maxlength="100"></label><label class="full">Sustento PDF<input type="file" accept="application/pdf" @change="fileSelected"><small>Máximo {{maxMb}} MB{{editing?' · vacío conserva el archivo actual':''}}.</small></label></div><footer><button type="button" class="soft" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':'Guardar'}}</button></footer></form></div></div></template>
<style scoped>
.page{--accent:#5d6fa8;color:#35464e}nav{margin-bottom:16px;color:#929fa5;font-size:.68rem}nav a{color:var(--accent);text-decoration:none}.hero{padding:20px 23px;display:flex;align-items:center;gap:14px;border-left:5px solid var(--accent);border-radius:12px;background:#fff}.mark{width:48px;height:48px;display:grid;place-items:center;flex:none;border-radius:10px;color:#fff;background:var(--accent);font-size:.6rem;font-weight:800}.hero small,.table-card small,.dialog small{color:var(--accent);font-size:.48rem;font-weight:800}.hero h1{margin:2px 0;font-size:1.3rem}.hero p{margin:0;color:#7e8a90;font-size:.67rem}.hero>strong{margin-left:auto;padding:6px 9px;border-radius:12px;color:var(--accent);background:#edf0f9;font-size:.52rem}.flash{padding:9px;border-radius:7px;color:#a64046;background:#fff0f0;font-size:.6rem}.success{color:#287052;background:#edf9f3}.filters{margin-top:10px;padding:12px;display:flex;align-items:end;gap:7px;border-radius:9px;background:#fff}.filters>label{width:310px}.filters form{display:flex;align-items:end;gap:5px;margin-right:auto}.filters form label{width:330px}.filters label,.dialog label{font-size:.5rem}.filters input,.filters select,.dialog input,.dialog select{width:100%;box-sizing:border-box;margin-top:4px;padding:8px;border:1px solid #d7dfe2;border-radius:6px;background:#fff;font:inherit;font-size:.54rem}.filters button,.table-card>footer button,.dialog footer button{padding:9px 12px;border:0;border-radius:6px;color:#fff;background:var(--accent);font-size:.52rem}.soft{color:#64727a!important;background:#edf1f3!important}.new{background:#287154!important}.table-card{margin-top:10px;border-radius:10px;background:#fff;overflow:hidden}.table-card>header{padding:13px 15px;border-bottom:1px solid #e7ebed}.table-card h2{margin:2px 0;font-size:.78rem}.scroll{overflow:auto}table{width:100%;min-width:1250px;border-collapse:collapse;font-size:.48rem}th,td{padding:9px;border-bottom:1px solid #e8ecee;text-align:left;vertical-align:middle}th{color:#fff;background:#526d79}td>b,td>small{display:block}.active,.inactive{display:inline-block;padding:4px 7px;border-radius:10px}.active{color:#287154;background:#e6f7ee}.inactive{color:#9d4046;background:#fdebed}.actions{display:flex;gap:4px}.actions button,.link{padding:6px 8px;border:0;border-radius:5px;font-size:.44rem}.edit{color:#3f5089;background:#e9edfa}.disable{color:#9d4046;background:#fdebed}.enable{color:#287154;background:#e6f7ee}.link{color:#405691;background:#e9edfa}.empty{padding:45px;text-align:center;font-size:.6rem}.table-card>footer{padding:10px;display:flex;align-items:center;justify-content:center;gap:10px;font-size:.52rem}.backdrop{position:fixed;z-index:100;inset:0;padding:18px;display:grid;place-items:center;background:#172b3daa}.dialog{width:min(900px,100%);max-height:94vh;padding:20px;box-sizing:border-box;border-radius:12px;background:#fff;overflow:auto}.dialog>header{display:flex;align-items:center;gap:10px}.dialog h2{margin:2px 0 12px;font-size:.9rem}.close{margin-left:auto;border:0;color:#59666c;background:none;font-size:1.3rem}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:8px 12px}.grid label small{display:block;margin-top:3px;color:#7e8a90}.full{grid-column:1/-1}.dialog>footer{margin-top:18px;display:flex;justify-content:flex-end;gap:7px}@media(max-width:900px){.hero,.filters,.filters form{flex-wrap:wrap}.hero>strong{margin-left:0}.filters>label,.filters form,.filters form label{width:100%}.grid{grid-template-columns:1fr}.full{grid-column:auto}}
</style>
